    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        
    String nome = txtNome.getText().trim();
    String cpf = txtCpf.getText().trim();
    String senha = new String(txtSenha.getPassword());
    
// Verifica se os campos foram preenchidos.
    if (nome.isEmpty() || cpf.isEmpty() || senha.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "Preencha todos os campos.");
        return;
}
// Verifica se o CPF tem 11 números.
    if (!cpf.matches("\\d{11}")) {
        javax.swing.JOptionPane.showMessageDialog(this,
             "O CPF deve conter 11 números, sem pontos ou traços.");
        return;
}

// Verifica se a senha tem exatamente 6 números.
    if (!senha.matches("\\d{6}")) {
        javax.swing.JOptionPane.showMessageDialog(this,
                "A senha deve conter exatamente 6 números.");
        return;
}

    try {
        InvestidorDAO dao = new InvestidorDAO();

        if (dao.consultarPorCpf(cpf) != null) {
            javax.swing.JOptionPane.showMessageDialog(this,
                    "Você já tem cadastro. Faça login.");
            return;
    }
        
        Investidor investidor = new Investidor(nome, cpf, senha);
        dao.inserir(investidor);
        dao.criarCarteira(cpf);

        int resposta = javax.swing.JOptionPane.showConfirmDialog(
            this,
                "Cadastro realizado com sucesso! Deseja acessar o menu principal agora?",
                    "Cadastro concluído",
                        javax.swing.JOptionPane.YES_NO_OPTION
);

        if (resposta == javax.swing.JOptionPane.YES_OPTION) {
            new TelaPrincipal1(investidor).setVisible(true);
            this.dispose();
} else {
    System.exit(0);
}

} catch (java.sql.SQLException e) {
    javax.swing.JOptionPane.showMessageDialog(this,
            "Erro ao cadastrar: " + e.getMessage());
}

    }//GEN-LAST:event_jButton1ActionPerformed

